import type { ComponentProps, ReactNode } from 'react'
import { cn } from '@/lib/utils'
import styles from './MediaObject.module.css'

export interface MediaObjectProps extends Omit<ComponentProps<'div'>, 'title'> {
  /** An Avatar, an Icon or an image beside the text. Decorative: the title names what it shows. */
  media: ReactNode
  /** What the object is: a person, a product, a comment's author. */
  title: ReactNode
  /** A line or a paragraph under the title. */
  description?: ReactNode
  /** Anything after the description: actions, or nested Media Objects for replies. */
  children?: ReactNode
  /** Where the media sits against the text: top, middle, bottom, or stretched to the text's full height. */
  align?: 'start' | 'center' | 'end' | 'stretch'
  /** Which side the media is on. */
  mediaPosition?: 'start' | 'end'
  /** Makes the title a heading of this level. Without it the title is bold text, right for a list of comments. */
  headingLevel?: 2 | 3 | 4
}

/**
 * Media beside a block of text: an avatar by a comment, an icon by a
 * setting, a thumbnail by a product. It owns no data and no landmark.
 */
export function MediaObject({
  media,
  title,
  description,
  children,
  align = 'start',
  mediaPosition = 'start',
  headingLevel,
  className,
  ...props
}: MediaObjectProps) {
  const Title = headingLevel ? (`h${headingLevel}` as const) : 'p'
  return (
    <div
      className={cn(styles.mediaObject, className)}
      data-align={align}
      data-media-position={mediaPosition}
      {...props}
    >
      <div className={styles.media} aria-hidden="true">
        {media}
      </div>
      <div className={styles.body}>
        <Title className={styles.title}>{title}</Title>
        {description && <div className={styles.description}>{description}</div>}
        {children}
      </div>
    </div>
  )
}

/* Media and text share a row while the text keeps 12rem; below that the
   text wraps under the media, so the pattern needs no breakpoint and works
   in an aside as on a full page. */
.mediaObject {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  gap: var(--space-cluster) var(--space-group);
  font-family: var(--font-sans);
  font-size: var(--text-body-sm);
  line-height: var(--leading-body-sm);
  color: var(--foreground);
}

.mediaObject[data-align='center'] {
  align-items: center;
}
.mediaObject[data-align='end'] {
  align-items: flex-end;
}
.mediaObject[data-align='stretch'] {
  align-items: stretch;
}
/* order, not row-reverse: the DOM (reading order) stays media first, and
   when the row wraps the media drops under the text at the start edge
   instead of hanging off the far end above it. */
.mediaObject[data-media-position='end'] > .media {
  order: 1;
}

/* An Icon takes the icon size; an Avatar or an image keeps its own. */
.media {
  display: flex;
  flex: none;
  font-size: var(--icon-md);
  color: var(--muted-foreground);
}

.body {
  display: grid;
  flex: 1 1 12rem;
  align-content: start;
  gap: var(--space-1);
  min-inline-size: 0;
}

.title {
  margin: 0;
  font-size: inherit;
  line-height: inherit;
  font-weight: 600;
  overflow-wrap: anywhere;
}

.description {
  color: var(--muted-foreground);
  overflow-wrap: anywhere;
}
.description > p {
  margin: 0;
}
